public class Demo {
    public static void main(String[] args) {
        System.out.println("Before literal");
        Class<?> c = Helper.class; // <clinit> does NOT run here
        System.out.println("Loaded: " + c.getName());
        new Helper(); // NOW <clinit> runs!
    }
}
class Helper {
    static { System.out.println("Helper initialized!"); }
}
